#include "sfx/platform/win32/file_payload_store.hpp"
#include <algorithm>
#include <iostream>
#include <stdexcept>
namespace app=sfx::application;
namespace native=sfx::platform::win32;
namespace ins=native::installation;
namespace {
unsigned checks{};
void check(bool passed,const char* reason){++checks;if(!passed)throw std::runtime_error(reason);}
template<class F>void rejected(F&& f,const char* reason){bool refused{};try{f();}catch(const std::exception&){refused=true;}check(refused,reason);}
void append(native::FilePayloadLease& file,std::string_view bytes){for(std::size_t offset=0;offset<bytes.size();offset+=65536){const auto chunk=bytes.substr(offset,65536);file.append(reinterpret_cast<const std::uint8_t*>(chunk.data()),chunk.size());}}
}
int main(int argc,char** argv){try{
    check(argc==2,"fresh owned-copy root required");const auto root=std::filesystem::absolute(argv[1]);check(!std::filesystem::exists(root),"never overwrite owned-copy evidence");std::filesystem::create_directories(root.parent_path());const auto who=ins::operator_sid();const auto sd=ins::mutable_descriptor(who);for(const auto& path:{root,root/L"Files",root/L"Files"/L"General",root/L"Source",root/L"Private"})ins::create_directory(std::filesystem::path(path).make_preferred(),sd.get());
    const auto source_dir=native::FilePayloadDirectory::private_store(root/L"Source",who),private_dir=native::FilePayloadDirectory::private_store(root/L"Private",who);const auto area=native::FilePayloadDirectory::area(root,L"Files/General",{},{},who);std::string bytes(200003,'x');bytes[65535]='z';bytes.back()='!';{auto file=source_dir.create("source.bin",bytes.size());append(file,bytes);file.identity();}auto source=source_dir.read("source.bin");const auto original=source.identity();
    const auto partial=[&](const native::FilePayloadDirectory& directory,const char* name,std::string_view content){auto file=directory.create(name,bytes.size()+1);append(file,content);file.flush();return file.object_identity();};
    const auto bound=partial(area,"partial.bin",std::string_view(bytes).substr(0,70001));{auto resumed=area.resume_owned_copy("partial.bin",bound,source);append(resumed,std::string_view(bytes).substr(70001));const auto complete=resumed.identity();check(complete.bytes==original.bytes&&complete.sha256==original.sha256&&complete.file_id==bound.file_id,"actual area copy resumes exact owned prefix without replacing native identity");}
    {auto resumed=area.resume_owned_copy("partial.bin",bound,source);check(resumed.identity().sha256==original.sha256,"complete-copy recovery does not append or duplicate bytes");}
    const auto wrong=partial(area,"wrong.bin","!");const auto wrong_before=area.read("wrong.bin").identity();rejected([&]{area.resume_owned_copy("wrong.bin",wrong,source);},"mismatching prefix refused without overwrite");check(area.read("wrong.bin").identity().sha256==wrong_before.sha256,"mismatching bytes preserved exactly");
    const auto unbound=partial(area,"unbound.bin",{});rejected([&]{area.resume_owned_copy("unbound.bin",{},source);},"create-before-journal-bind orphan is never adopted");check(area.read("unbound.bin").identity().bytes==0,"unbound native object remains intact");auto changed=unbound;changed.file_id+="9";rejected([&]{area.resume_owned_copy("unbound.bin",changed,source);},"changed native identity refuses");
    const auto excess=partial(area,"excess.bin",bytes+"?");rejected([&]{area.resume_owned_copy("excess.bin",excess,source);},"excess destination bytes refuse instead of truncating");check(area.read("excess.bin").identity().bytes==bytes.size()+1,"excess bytes retained");
    const auto cancelled=partial(area,"cancelled.bin",std::string_view(bytes).substr(0,70001));unsigned source_hashes{};rejected([&]{area.resume_owned_copy("cancelled.bin",cancelled,source,[&](auto done,auto total){if(done==total&&total==bytes.size())++source_hashes;return source_hashes<2||done!=0;});},"cancellation during prefix verification stops before append");check(area.read("cancelled.bin").identity().bytes==70001,"cancelled prefix remains intact");{auto resumed=area.resume_owned_copy("cancelled.bin",cancelled,source);append(resumed,std::string_view(bytes).substr(70001));check(resumed.identity().sha256==original.sha256,"same bound copy retries after cancellation");}
    const auto busy=partial(area,"busy.bin",std::string_view(bytes).substr(0,10));{auto reader=area.read("busy.bin");rejected([&]{area.resume_owned_copy("busy.bin",busy,source);},"busy destination cannot gain writable lease");}check(area.read("busy.bin").identity().bytes==10,"busy copy retained");
    rejected([&]{source_dir.resume_owned_copy("source.bin",source.object_identity(),source);},"source and destination cannot alias");const auto imported=native::FilePayloadDirectory::import_source(area.path(),{},who,true);rejected([&]{imported.resume_owned_copy("busy.bin",busy,source);},"import-source capability never becomes output");
    const auto constrained=partial(private_dir,"constrained.bin",std::string_view(bytes).substr(0,10));const auto limited=native::FilePayloadDirectory::private_store(private_dir.path(),who,[]{return native::kFilePayloadFreeReserve+100;});rejected([&]{limited.resume_owned_copy("constrained.bin",constrained,source);},"remaining copy must reserve real space under reduced test ceiling");check(private_dir.read("constrained.bin").identity().bytes==10,"space refusal keeps partial bytes");
    const auto linked=partial(area,"linked.bin",std::string_view(bytes).substr(0,10));check(CreateHardLinkW((area.path()/L"alias.bin").c_str(),(area.path()/L"linked.bin").c_str(),nullptr)!=FALSE,"isolated native hardlink negative fixture");rejected([&]{area.resume_owned_copy("linked.bin",linked,source);},"linked new object cannot resume");check(source.identity().sha256==original.sha256,"all negative cases preserve exact source content");
    #include "ftn_generated_bytes_checks.inc"
    std::cout<<"PASS "<<checks<<" actual NTFS owned-copy/generated-metadata prefix/retry/identity/unbound/excess/busy/alias/link/cancellation checks; reduced free-space ceiling, no full TIC journal or cross-volume claim\n";return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<checks<<": "<<e.what()<<'\n';return 1;}}
